                    let cand = n.to_string();
                    if !names.contains(&cand) {
                        break cand;
                    }
                    n += 1;
                }
            }
        }
    };
    let id = pr.alloc_id();
    pr.elements.insert(
        id,
        jobj! {
            "guid" => crate::rand::guid(),
            "category" => "grid",
            "name" => name.clone(),
            "start" => start,
            "end" => end,
        },
    );
    Ok(jobj! {"id" => id, "name" => name})
}

