    /// A project read from a file: from an older format, brought up to this one; from a newer, refused, saying so.
    pub fn from_json(text: &str) -> Result<Model, String> {
        Model::read(text).map(|(m, _)| m)
    }

    /// Read from a project file, with what this BIMCraft doesn't know of it left out: a field a newer one added, or a
    /// misspelled one. The fields left out come back as JSON pointers into the file (`/elements/100004/finish`). A file
    /// of a newer format is refused whole, since what changed may be more than a field.
    pub fn read(text: &str) -> Result<(Model, Vec<String>), String> {
        use crate::lenient;
        use serde_json::Value;
        let mut v: Value = serde_json::from_str(text).map_err(|e| e.to_string())?;
        let format = v.get("format").map_or(Some(0), Value::as_u64).ok_or("`format` must be a whole number")?;
        if format > u64::from(FORMAT) {
            return Err(format!(
                "it was saved by a newer BIMCraft (file format {format}; this one reads up to {FORMAT}): update BIMCraft to open it"
            ));
        }
        if format < 4 {
            pens_from_pixels(&mut v);
        }
        let mut left_out = Vec::new();
        // An element is an internally tagged enum, which serde reads whole: each is looked into as its category's struct.
        let mut elements = v.get_mut("elements").map_or(Value::Null, Value::take);
        if let Value::Object(es) = &mut elements {
            for (id, e) in es.iter_mut() {
                let mut bare = e.clone();
                let category = bare.as_object_mut().and_then(|o| {
                    o.remove("guid");
                    o.remove("category")
                });
                for p in lenient::element(category.as_ref().and_then(Value::as_str).unwrap_or(""), &bare) {
                    lenient::remove(e, &p);
                    left_out.push(format!("/elements/{id}{p}"));
                }
            }
        }
        // A detail group's members are elements too, held by their type, and are looked into the same way.
        if let Some(Value::Object(groups)) = v.get_mut("detail_groups") {
            for (name, group) in groups.iter_mut() {
                let Some(Value::Array(members)) = group.get_mut("members") else { continue };
                for (i, member) in members.iter_mut().enumerate() {
                    let Some(e) = member.get_mut("element") else { continue };
                    let mut bare = e.clone();
                    let category = bare.as_object_mut().and_then(|o| o.remove("category"));
                    for p in lenient::element(category.as_ref().and_then(Value::as_str).unwrap_or(""), &bare) {
                        lenient::remove(e, &p);
                        left_out.push(format!("/detail_groups/{}/members/{i}/element{p}", lenient::escaped(name)));
                    }
                }
            }
        }
        if v.is_object() {
            v["elements"] = Value::Object(serde_json::Map::new());
        .collect();
    out.sort_by(|a, b| a.0.cmp(&b.0));
    out
}

/// The key an element's `params` holds a project parameter's value under (its GUID).
pub fn key_of(pr: &Project, name: &str) -> Option<String> {
    pr.lib_guid(LIB, name)
}

/// Whether a key of an element's `params` is this parameter's (its GUID, or its name).
fn is_key(k: &str, guid: &Option<String>, name: &str) -> bool {
    k == name || guid.as_deref() == Some(k)
}

fn cats_of(v: &Value) -> Vec<String> {
    v.get("categories")
        .and_then(|c| c.as_arr())
        .map(|a| a.iter().filter_map(|x| x.as_str().map(|s| s.to_string())).collect())
        .unwrap_or_default()
}

/// Whether any element holds a value of it.
fn has_values(pr: &Project, guid: &Option<String>, name: &str) -> bool {
    pr.elements.values().any(|e| {
        e.get("params")
            .and_then(|p| p.as_obj())
            .map(|m| m.keys().any(|k| is_key(k, guid, name)))
            .unwrap_or(false)
    })
}

/// The first view filter (by name) with a rule on it, among those of these categories (any, for None).
fn filter_with_rule(pr: &Project, guid: &Option<String>, name: &str, cats: Option<&[String]>) -> Option<String> {
    let filters = section(pr, "view_filters");
    let mut names: Vec<&String> = filters.keys().collect();
    names.sort();
    for fname in names {
        let f = filters.get(fname).unwrap();
        if let Some(cats) = cats {
            let fc = cats_of(f);
            if !fc.iter().any(|c| cats.contains(c)) {
                continue;
            }
        }
        let rules = f.get("rules").and_then(|r| r.as_arr()).cloned().unwrap_or_default();
        if rules.iter().any(|r| r.get("field").and_then(|x| x.as_str()).map(|x| is_key(x, guid, name)).unwrap_or(false)) {
            return Some(fname.clone());
        }
    }
    None
}

/// Takes the parameter's values off the elements (of these categories; all, for None), and its
/// fields, filters and sorts off the schedules of them.
fn strip(pr: &mut Project, guid: &Option<String>, name: &str, cats: Option<&[String]>) {
    for e in pr.elements.values_mut() {
        let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
        if cat == "schedule" {
            let of = e.get("of").and_then(|c| c.as_str()).unwrap_or("").to_string();
            if cats.map(|cs| cs.contains(&of)).unwrap_or(true) {
                strip_schedule(e, guid, name);
            }
            continue;
        }
        if !cats.map(|cs| cs.contains(&cat)).unwrap_or(true) {
            continue;
        }
        let mut empty = false;
        if let Some(Value::Obj(m)) = e.get_mut("params") {
            m.items.retain(|(k, _)| !is_key(k, guid, name));
            empty = m.is_empty();
        }
        if empty {
            e.remove("params");
        }
    }
}

fn strip_schedule(e: &mut Value, guid: &Option<String>, name: &str) {
    for (list, key) in [("fields", "name"), ("filters", "field"), ("sort", "field")] {
        let mut empty = false;
        if let Some(Value::Arr(a)) = e.get_mut(list) {
            let before = a.len();
            a.retain(|x| !x.get(key).and_then(|f| f.as_str()).map(|f| is_key(f, guid, name)).unwrap_or(false));
            empty = a.is_empty() && before > 0;
        }
        if empty {
            e.remove(list);
        }
    }
}

fn shown(v: &Value) -> Value {
